<?php require_once 'includes/db.php';$s=db()->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}$title=$p['name'].' - '.APP_NAME;include 'includes/header.php';?><div class="product"><div><img src="<?=htmlspecialchars($p['image'])?>"></div><div><h1><?=htmlspecialchars($p['name'])?></h1><p><?=nl2br(htmlspecialchars($p['description']))?></p><div class="price">KES <?=number_format($p['price'],2)?></div><p>Stock: <?=$p['stock']?></p><form method="post" action="cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Quantity <input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1"></label><button class="btn">Add to Cart</button></form></div></div><?php include 'includes/footer.php';?>